import{_ as s,C as n,o as i,c as l,aj as o,E as r,j as d,a}from"./framework.js";const p=JSON.parse('{"title":"角色权限 | Cms / Settings | Documentation","description":"角色权限定义本站 站点角色 可访问的后台 feature 与 action（查看 / 编辑 / 删除等）。在 站点用户 中为成员指定角色后，其登录后台时的菜单、按钮与 API 调用均受本页配置约束。","frontmatter":{"title":"角色权限 | Cms / Settings | Documentation","description":"角色权限定义本站 站点角色 可访问的后台 feature 与 action（查看 / 编辑 / 删除等）。在 站点用户 中为成员指定角色后，其登录后台时的菜单、按钮与 API 调用均受本页配置约束。","head":[["link",{"rel":"canonical","href":"https://docs.kooboo.com/zh/cms/settings/roles.html"}]]},"headers":[],"relativePath":"zh/cms/settings/roles.md","filePath":"cms/settings/roles.md","lastUpdated":1780907394000}'),c={name:"zh/cms/settings/roles.md"};function h(g,t,b,m,u,_){const e=n("DocImage");return i(),l("div",null,[t[0]||(t[0]=o('<h1 id="角色权限" tabindex="-1">角色权限 <a class="header-anchor" href="#角色权限" aria-label="Permalink to &quot;角色权限&quot;">​</a></h1><blockquote><p>菜单：<strong>站点设置 → 角色权限</strong>（高级菜单）<br> 深链：<code>/_Admin/system/roles?SiteId={站点GUID}</code></p></blockquote><p><strong>角色权限</strong>定义本站 <strong>站点角色</strong> 可访问的后台 <strong>feature</strong> 与 <strong>action</strong>（查看 / 编辑 / 删除等）。在 <a href="./site-users.html">站点用户</a> 中为成员指定角色后，其登录后台时的菜单、按钮与 API 调用均受本页配置约束。</p><div class="tip custom-block"><p class="custom-block-title">权限</p><table tabindex="0"><thead><tr><th>操作</th><th>权限</th></tr></thead><tbody><tr><td>查看角色列表</td><td><code>role</code></td></tr><tr><td><strong>添加角色</strong>、编辑权限并 <strong>保存</strong></td><td><code>role·edit</code></td></tr><tr><td>多选 <strong>删除</strong> 自定义角色</td><td><code>role·delete</code></td></tr></tbody></table></div><div class="info custom-block"><p class="custom-block-title">高级菜单</p><p>本菜单在路由上标记为 <code>advanced: true</code>，除勾选 <strong>站点设置</strong> 分组外，还须能在 <a href="./../navigation.html#权限与编辑菜单">编辑菜单</a> 中看到 <strong>角色权限</strong> 子项（或由 <code>master</code> 等全权限角色访问）。</p></div><h2 id="如何打开" tabindex="-1">如何打开 <a class="header-anchor" href="#如何打开" aria-label="Permalink to &quot;如何打开&quot;">​</a></h2><ol><li>在 <a href="./../navigation.html#权限与编辑菜单">编辑菜单</a> 中勾选 <strong>站点设置 → 角色权限</strong>。</li><li>左侧 <strong>站点设置 → 角色权限</strong>。</li></ol>',7)),r(e,{src:"/cms/settings/settings-roles-overview.png",alt:"角色权限",width:"1120"}),t[1]||(t[1]=o('<h2 id="工具栏" tabindex="-1">工具栏 <a class="header-anchor" href="#工具栏" aria-label="Permalink to &quot;工具栏&quot;">​</a></h2><table tabindex="0"><thead><tr><th>控件</th><th>说明</th></tr></thead><tbody><tr><td><strong>添加角色</strong></td><td>打开 <a href="#添加或编辑角色">添加角色弹窗</a>，新建自定义角色并勾选权限</td></tr></tbody></table>',2)),r(e,{src:"/cms/settings/settings-roles-toolbar.png",alt:"角色权限工具栏",width:"1120"}),t[2]||(t[2]=o('<h2 id="角色列表" tabindex="-1">角色列表 <a class="header-anchor" href="#角色列表" aria-label="Permalink to &quot;角色列表&quot;">​</a></h2><table tabindex="0"><thead><tr><th>列</th><th>说明</th></tr></thead><tbody><tr><td><strong>角色名</strong></td><td><code>name</code>，以标签展示</td></tr><tr><td><strong>编辑</strong></td><td>铅笔按钮，打开权限编辑弹窗</td></tr></tbody></table><p>列表含 <strong>内置角色</strong> 与 <strong>自定义角色</strong>，按创建时间倒序。内置三项 <strong><code>master</code></strong>、<strong><code>developer</code></strong>、<strong><code>contentmanager</code></strong> 的复选框 <strong>不可选</strong>（不可批量删除），但仍可 <strong>编辑</strong> 其权限并保存到站点的 <code>RolePermission</code> 仓库。</p>',3)),r(e,{src:"/cms/settings/settings-roles-list.png",alt:"角色列表",width:"1120"}),t[3]||(t[3]=o('<h3 id="内置角色-概览" tabindex="-1">内置角色（概览） <a class="header-anchor" href="#内置角色-概览" aria-label="Permalink to &quot;内置角色（概览）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>角色名</th><th>说明</th></tr></thead><tbody><tr><td><strong>master</strong></td><td>默认拥有全部已注册 feature 权限（全选）</td></tr><tr><td><strong>developer</strong></td><td>预置开发相关 feature（页面、Code、数据库、服务集成、Hook 等）</td></tr><tr><td><strong>contentmanager</strong></td><td>预置内容与电商运营相关 feature（内容、媒体、商品等）</td></tr></tbody></table><p>具体 feature 集合以 Kooboo 版本内 <code>PermissionService.EmbeddedRoles</code> 为准；可在后台 <strong>编辑</strong> 查看或微调后保存。</p><h3 id="删除限制" tabindex="-1">删除限制 <a class="header-anchor" href="#删除限制" aria-label="Permalink to &quot;删除限制&quot;">​</a></h3><ul><li><strong>内置角色</strong> 不可删除。</li><li><strong>自定义角色</strong> 若仍有 <a href="./site-users.html">站点用户</a> 的 <code>SiteRole</code> 引用，删除时会报错（<em>The role is in use and cannot be deleted</em>）。</li></ul><h2 id="添加或编辑角色" tabindex="-1">添加或编辑角色 <a class="header-anchor" href="#添加或编辑角色" aria-label="Permalink to &quot;添加或编辑角色&quot;">​</a></h2>',6)),r(e,{src:"/cms/settings/settings-roles-add-dialog.png",alt:"添加角色弹窗",width:"1120"}),t[4]||(t[4]=d("p",null,[a("编辑已有角色时弹窗标题为 "),d("strong",null,"编辑角色"),a("，"),d("strong",null,"角色名"),a(" 输入框 "),d("strong",null,"禁用"),a("（不可改名）；新建时须填写唯一名称（1～50 字符，且不能与内置角色名冲突）。")],-1)),r(e,{src:"/cms/settings/settings-roles-edit-dialog.png",alt:"编辑角色权限",width:"1120"}),t[5]||(t[5]=o('<h3 id="权限面板" tabindex="-1">权限面板 <a class="header-anchor" href="#权限面板" aria-label="Permalink to &quot;权限面板&quot;">​</a></h3><table tabindex="0"><thead><tr><th>区域</th><th>说明</th></tr></thead><tbody><tr><td><strong>全选</strong></td><td>勾选/取消当前角色全部 permission</td></tr><tr><td><strong>Feature 列</strong></td><td>每项对应一个 <code>feature</code>（如 <code>pages</code>、<code>content</code>、<code>domain</code>），文案来自后台国际化（如「页面」「域名管理」「服务集成」）</td></tr><tr><td><strong>单项复选框</strong></td><td>仅含一种 action 的 feature 直接勾选</td></tr><tr><td><strong>带下拉的 Feature</strong></td><td>点击标签弹出 <strong>查看 / 编辑 / 删除</strong>（及 <code>debug</code> 等）子项；可对该 feature <strong>全选</strong></td></tr></tbody></table><p>勾选 <strong>编辑</strong>、<strong>删除</strong> 或 <strong>debug</strong> 时，会自动勾选同 feature 的 <strong>查看</strong>；若子项仍选中，则 <strong>查看</strong> 不可单独取消。含多种 action 的 feature 点击标签可展开子复选框（如 <strong>查看 / 编辑 / 删除</strong>）。</p><p>保存调用 <code>Role/post</code>，写入站点 <code>RolePermissionRepository</code>。</p><h2 id="feature-与后台菜单" tabindex="-1">feature 与后台菜单 <a class="header-anchor" href="#feature-与后台菜单" aria-label="Permalink to &quot;feature 与后台菜单&quot;">​</a></h2><p>权限项由服务端 <code>PermissionService.GetList()</code> 汇总各 API 的 <code>[Permission]</code> 特性生成；新增 Kooboo 版本可能增加 feature。常见对应关系示例：</p><table tabindex="0"><thead><tr><th>feature（部分）</th><th>后台能力</th></tr></thead><tbody><tr><td><code>pages</code></td><td>页面设计与路由</td></tr><tr><td><code>content</code> / <code>contentType</code></td><td>内容与数据类型</td></tr><tr><td><code>database</code></td><td>数据库菜单</td></tr><tr><td><code>config</code></td><td><a href="./integrations/">服务集成</a></td></tr><tr><td><code>domain</code></td><td><a href="./domains.html">域名管理</a></td></tr><tr><td><code>siteUser</code> / <code>role</code></td><td><a href="./site-users.html">站点用户</a>、本页</td></tr><tr><td><code>frontEvents</code> / <code>backendEvents</code></td><td><a href="./request-hooks.html">请求 Hook</a>、<a href="./action-hooks.html">操作 Hook</a></td></tr><tr><td><code>commerce*</code> 系列</td><td>电商各子菜单</td></tr></tbody></table><p>左侧菜单可见性还会受前端 <strong>角色菜单过滤</strong>（运营/设计师/开发者预设）影响；API 与按钮仍以本页勾选的 <strong>Permissions</strong> 为准。</p><h2 id="与站点用户的关系" tabindex="-1">与站点用户的关系 <a class="header-anchor" href="#与站点用户的关系" aria-label="Permalink to &quot;与站点用户的关系&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th><strong>角色权限（本页）</strong></th><th><a href="./site-users.html">站点用户</a></th></tr></thead><tbody><tr><td>回答</td><td>某角色 <strong>能做什么</strong></td><td><strong>谁</strong> 拥有某角色</td></tr><tr><td>顺序</td><td>通常 <strong>先</strong> 定义或确认角色</td><td><strong>再</strong> 把成员加入站点并选角色</td></tr></tbody></table><h2 id="典型工作流" tabindex="-1">典型工作流 <a class="header-anchor" href="#典型工作流" aria-label="Permalink to &quot;典型工作流&quot;">​</a></h2><ol><li>查看内置 <code>developer</code> / <code>contentmanager</code> 是否满足团队分工，必要时 <strong>编辑</strong> 微调。</li><li>若无合适预设，<strong>添加角色</strong>（如 <code>content-editor</code>），按 feature 勾选权限并 <strong>保存</strong>。</li><li>在 <a href="./site-users.html">站点用户</a> 把协作者加入本站并分配角色。</li><li>让对方登录验证菜单与关键操作；权限不足时回到本页调整。</li><li>停用角色前，先移除或改派所有引用该角色的站点用户，再 <strong>删除</strong> 自定义角色。</li></ol><h2 id="相关" tabindex="-1">相关 <a class="header-anchor" href="#相关" aria-label="Permalink to &quot;相关&quot;">​</a></h2><table tabindex="0"><thead><tr><th>文档</th><th>说明</th></tr></thead><tbody><tr><td><a href="./">站点设置概述</a></td><td>菜单总览</td></tr><tr><td><a href="./site-users.html">站点用户</a></td><td>成员与角色绑定</td></tr><tr><td><a href="./../navigation.html#权限与编辑菜单">编辑菜单</a></td><td>菜单显示与高级项</td></tr></tbody></table>',14))])}const P=s(c,[["render",h]]);export{p as __pageData,P as default};
